class _ConnRowIndex:
    """Compact bodyId -> row-index map for the in-memory connection DB.

    Replaces the former dict-of-Python-lists indexes (measured ~97 MB per
    million rows: every row index is an individual 28-byte int object
    inside a list slot, plus dict-table slack).  One int32 array of row
    indices plus a bodyId -> (start, end) offset dict is ~8x smaller at
    10M rows and exposes the read-only dict API the consumers use
    (``get`` / ``__contains__`` / ``__getitem__`` / ``keys`` / ``__iter__``
    / ``__len__`` / ``__bool__``).
    """

    __slots__ = ('_data', '_offsets', '_keys')

    def __init__(self):
        self._data = np.empty(0, dtype=np.int32)
        self._offsets = {}
        self._keys = []

    @classmethod
    def from_groups(cls, groups):
        """Build from ``(key, iterable_of_row_indices)`` pairs in key order."""
        index = cls()
        offsets = {}
        keys = []
        chunks = []
        pos = 0
        for key, idx_list in groups:
            idx_arr = np.asarray(idx_list, dtype=np.int32)
            offsets[key] = (pos, pos + idx_arr.size)
            keys.append(key)
            chunks.append(idx_arr)
            pos += idx_arr.size
        index._data = (
            np.concatenate(chunks)
            if chunks else np.empty(0, dtype=np.int32)
        )
        index._offsets = offsets
        index._keys = keys
        return index

    @classmethod
    def from_dict(cls, mapping):
        return cls.from_groups(mapping.items())

    def get(self, key, default=None):
        span = self._offsets.get(key)
        if span is None:
            return default
        start, end = span
        return self._data[start:end].tolist()

    def __getitem__(self, key):
        span = self._offsets.get(key)
        if span is None:
            raise KeyError(key)
        start, end = span
        return self._data[start:end].tolist()

    def __contains__(self, key):
        return key in self._offsets

    def keys(self):
        return list(self._keys)

    def __iter__(self):
        return iter(self._keys)

    def __len__(self):
        return len(self._offsets)

    def __bool__(self):
        return bool(self._offsets)

    def __repr__(self):
        return (f'_ConnRowIndex(entries={len(self._offsets)}, '
                f'rows={self._data.size})')


def _id_set_digest(ids) -> str:
    """
    Build a stable, collision-safe digest for a set of neuron IDs.

    The digest is deterministic (unlike Python's per-process ``hash()``) and
    is used inside the FindAllPath graph-cache key.  Two queries that differ
    only in the *order* of the same IDs still map to the same key, while two
    queries with different ID sets map to different keys.
    """
    import hashlib
    joined = "|".join(sorted({str(i) for i in ids}))
    return hashlib.md5(joined.encode("utf-8", "surrogatepass")).hexdigest()[:24]


def _parse_path_nodes(path_str_val):
    """Parse a path-column value into its node sequence.

    A value may already be a sequence (fresh in-memory frame), a Python
    list-literal string (parquet/CSV round-trip), or an ``'A->B->C'``
    joined string.  Parsing must never execute code, hence
    ``ast.literal_eval`` — never ``eval`` — for persisted strings.
    """
    if not isinstance(path_str_val, str):
        return path_str_val
    try:
        return ast.literal_eval(path_str_val)
    except Exception:
        # ValueError/SyntaxError for malformed literals; TypeError for
        # unhashable dict/set keys (e.g. '{[1]: 2}'). Any parse failure
        # degrades to the '->' split — never propagates, never executes.
        return path_str_val.split('->')


def _path_has_unconserved_edge(path_str_val, conserved_edge_set):
    """Whether a path contains any edge outside the conserved edge set."""
    if path_str_val is None:
        return True
    nodes = _parse_path_nodes(path_str_val)
    for i in range(len(nodes) - 1):
        edge = (str(nodes[i]).strip(), str(nodes[i + 1]).strip())
        if edge not in conserved_edge_set:
            return True
    return False


def _findallpath_cache_key(
    dataset_safe: str,
    source_ID,
    target_ID,
    max_interlayer,
    separate_hemispheres: bool,
    filter_by: str,
    min_ratio: float,
    min_traversal_probability: float,
    exclude_intra_type_connections: bool,
    drop_untyped: bool = True,
    hemisphere_filter: str = 'both',
    weight_basis: str = 'synapse',
) -> str:
    """
    Build the FindAllPath graph-cache key.

    The key must include every parameter that changes which edges the
    graph contains - not only the topology (source/target/interlayer) but
    also the connection filters applied during fetching (filter_by level,
    ratio/probability thresholds, intra-type exclusion, hemisphere mode —
    BOTH ``separate_hemispheres`` and ``hemisphere_filter`` (the left/
    right edge filter runs at fetch time even when hemisphere-aware
    splitting is off) — and the untyped-neuron drop). Otherwise a later
    run with different filters would silently reuse a graph built under
    different filter conditions. ``weight_basis`` segments the ratio lane
    from synapse entries (the stored graphs are pre-threshold at fetch
    floor, so the universes coincide, but the entry bookkeeping stays
    per-basis; plan-connection-ratio-pathfinding §16.2).

    ``max_interlayer=None`` (FindShortestPath) omits the depth from the
    key, but note that shortest mode never READS or WRITES this cache at
    all: its target-rooted discovery (``use_cached_graph`` is only armed
    after discovery) makes forward-graph entries non-interchangeable, so
    the depth field on existing entries is informational only.
    """
    source_hash = _id_set_digest(source_ID)
    target_hash = _id_set_digest(target_ID)
    hemi_flag = f"hemi-{hemisphere_filter}" if separate_hemispheres else f"nohemi-{hemisphere_filter}"
    filters = (
        f"{filter_by}|{min_ratio}|{min_traversal_probability}|"
        f"{int(bool(exclude_intra_type_connections))}|"
        f"{int(bool(drop_untyped))}|basis-{weight_basis}"
    )
    depth_part = f"{max_interlayer}_" if max_interlayer is not None else ""
    return (
        f"{dataset_safe}_{source_hash}_{target_hash}_{depth_part}"
        f"{hemi_flag}_{filters}"
    )


def _findallpath_cache_entry_bytes(entry: dict) -> int:
    """Best-effort resident-size estimate for one graph-cache entry.

    Layer tables dominate; each Polars frame reports its exact footprint
    via ``estimated_size()``.  Pandas frames and neuron-id sets are
    approximated (str objects ~60 B, one set slot ~60 B per id).
    """
    total = 0
    for table in entry.get('all_connections', []) or []:
        if hasattr(table, 'estimated_size'):
            try:
                total += int(table.estimated_size())
                continue
            except Exception:
                pass
        if hasattr(table, 'memory_usage'):
            try:
                total += int(table.memory_usage(deep=True).sum())
                continue
            except Exception:
                pass
        total += len(table) * 64
    id_sets = list(entry.get('layer_neurons', []) or [])
    if entry.get('all_neurons_in_network') is not None:
        id_sets.append(entry['all_neurons_in_network'])
    for id_set in id_sets:
        total += len(id_set) * 120
    return total


def _findallpath_cache_put(key: str, entry: dict) -> None:
    """Insert into the FindAllPath graph cache, evicting the oldest entry.

    Eviction is FIFO by count AND by resident size: each entry holds the
    full discovery graph (layer tables), so a handful of wide queries can
    pin multiple GB for the rest of the process in long-lived sessions
    (comparison runs, notebooks).  The budget keeps that bounded.
    """
    global _FINDALLPATH_GRAPH_CACHE
    _FINDALLPATH_GRAPH_CACHE[key] = entry
    while len(_FINDALLPATH_GRAPH_CACHE) > _FINDALLPATH_CACHE_MAX:
        _FINDALLPATH_GRAPH_CACHE.pop(next(iter(_FINDALLPATH_GRAPH_CACHE)))
    budget = _FINDALLPATH_CACHE_BUDGET_BYTES
    total = sum(
        _findallpath_cache_entry_bytes(cached)
        for cached in _FINDALLPATH_GRAPH_CACHE.values()
    )
    while total > budget and len(_FINDALLPATH_GRAPH_CACHE) > 1:
        oldest = next(iter(_FINDALLPATH_GRAPH_CACHE))
        total -= _findallpath_cache_entry_bytes(_FINDALLPATH_GRAPH_CACHE.pop(oldest))


def _layer_table_edge_pairs(conn_df):
    """
    Return the set of (pre, post) edge pairs stored in a connection table.

    Accepts either a Polars or a Pandas DataFrame.  Empty tables return an
    empty set.
    """
    if conn_df is None:
        return set()
    try:
        if conn_df.is_empty():
            return set()
    except AttributeError:
        if conn_df.empty:
            return set()
    # Polars Series exposes .to_list(), Pandas exposes .tolist()
    try:
        pre = list(conn_df['bodyId_pre'].to_list())
        post = list(conn_df['bodyId_post'].to_list())
    except AttributeError:
        pre = list(conn_df['bodyId_pre'].tolist())
        post = list(conn_df['bodyId_post'].tolist())
    return set(zip((str(p) for p in pre), (str(p) for p in post)))


def _match_path_edges_to_layers(edges_in_paths, conn_layers):
    """
    Match the edges that appear on valid paths against the fetched layer
    tables.

    Paths are found on a graph built from the union of all layer tables, so
    a path edge's *position* in the path is NOT the same as the layer table
    that actually contains the row (e.g. reciprocal/recurrent edges, or a
    neuron reachable through a longer route than its discovery layer).
    Matching against the real table rows instead of the path position keeps
    every occurrence of a path edge and never drops real connections.

    The layer side is matched through a Polars join: materializing a full
    layer table as Python (pre, post) string tuples costs ~1 GB per
    million-row layer, while the join only touches the columns involved
    and converts back just the (small) matched subset.

    Parameters
    ----------
    edges_in_paths : set of (pre, post) tuples
        Unique edges that appear on at least one valid path.
    conn_layers : iterable of DataFrames
        Per-layer connection tables (Polars or Pandas), in layer order.

    Returns
    -------
    (valid_pairs_by_layer, matched_edges)
        valid_pairs_by_layer: list parallel to conn_layers with the path
        edges present in each layer's table.
        matched_edges: union of all valid pairs found in any layer table.
    """
    edges_in_paths = set(edges_in_paths or ())
    valid_pairs_by_layer = []
    matched_edges = set()
    if not edges_in_paths:
        return [set() for _ in conn_layers], matched_edges

    # The path-edge side is small (bounded by edges on found paths);
    # materialize it once as a frame and join each layer against it.
    pairs_df = pl.DataFrame(
        list(edges_in_paths),
        schema=[('bodyId_pre', pl.Utf8), ('bodyId_post', pl.Utf8)],
        orient='row',
    )

    for conn_df in conn_layers:
        if conn_df is None:
            valid_pairs_by_layer.append(set())
            continue
        try:
            is_empty = conn_df.is_empty()
        except AttributeError:
            is_empty = conn_df.empty
        if is_empty:
            valid_pairs_by_layer.append(set())
            continue
        try:
            layer_df = (
                conn_df
                if isinstance(conn_df, pl.DataFrame)
                else pl.from_pandas(conn_df)
            )
            layer_pairs = layer_df.select(
                pl.col('bodyId_pre').cast(pl.Utf8),
                pl.col('bodyId_post').cast(pl.Utf8),
            ).unique()
            matched = pairs_df.join(
                layer_pairs, on=['bodyId_pre', 'bodyId_post'], how='inner'
            )
            valid = set(
                zip(matched['bodyId_pre'].to_list(),
                    matched['bodyId_post'].to_list())
            )
        except Exception:
            # Odd schemas (missing/renamed id columns): keep the historical
            # row-materializing path as the fallback.
            layer_edges = _layer_table_edge_pairs(conn_df)
            valid = edges_in_paths & layer_edges
        valid_pairs_by_layer.append(valid)
        matched_edges |= valid
    return valid_pairs_by_layer, matched_edges


def prune_layers_hop_budget(conn_layers, sources, targets, bound,
                            pre_col='bodyId_pre', post_col='bodyId_post',
                            vprint=None, warn_notes=None, label='bodyId',
                            max_passes=4, report_bottleneck_bound=True):
    """Lossless hop-budget pruning of the discovery layer tables, iterated
    to a fixpoint.

    Each pass drops every edge (u, v) that cannot lie on ANY simple
    source->target path within ``bound`` edges: BFS hop distances distS(.)
    from the sources and distT(.) to the targets over the current tables,
    then keep row (u, v) iff distS(u) + 1 + distT(v) <= bound (see
    ``_hop_budget_pass_once`` for the exactness argument). Passes repeat on
    the already-pruned tables until a pass drops nothing or ``max_passes``
    is reached. Iteration is still lossless — every admissible path
    survives every pass — and distances recomputed on the pruned graph can
    only grow, so each pass can only surface more dead edges whose routes
    died with earlier drops: the "lossless, not complete" gap narrows
    monotonically.

    Unlike ``_trim_edges_with_path_integrity`` (a strength-based trim with
    a lossy budget), this pass is applied at EVERY depth and in both path
    modes; no admissible path is removed, so threshold-monotonicity and
    downstream replay semantics are unaffected.

    Returns (pruned_tables, stats). Inputs are never mutated — the cached
    FindAllPath graph entries stay shareable across thresholds. ``stats``
    reports rows_before/rows_dropped/nodes/strongest_retained plus
    ``passes`` (the number of passes actually run; 1 reproduces the
    historical single-pass behavior, which fit_edge_budget probes use).
    """
    stats = {'rows_before': 0, 'rows_dropped': 0, 'nodes': 0,
             'strongest_retained': None, 'passes': 0}
    tables = [
        c for c in (conn_layers or [])
        if not (c.is_empty() if hasattr(c, 'is_empty') else c.empty)
    ]
    if not tables or bound is None or bound < 1:
        return conn_layers, stats
    stats['rows_before'] = sum(
        t.height if hasattr(t, 'height') else len(t) for t in tables)

    current = tables
    dropped_total = 0
    anchored = True
    for _ in range(max(1, int(max_passes))):
        current, pstats = _hop_budget_pass_once(
            current, sources, targets, bound,
            pre_col=pre_col, post_col=post_col, label=label)
        stats['passes'] += 1
        dropped_total += pstats['rows_dropped']
        if pstats['nodes'] and not stats['nodes']:
            stats['nodes'] = pstats['nodes']
        if pstats['strongest_retained'] is not None:
            stats['strongest_retained'] = pstats['strongest_retained']
        anchored = pstats['anchored']
        if pstats['rows_dropped'] == 0 or not anchored:
            break
    stats['rows_dropped'] = dropped_total
    if not anchored and stats['passes'] == 1:
        # No BFS anchor in the tables at all (e.g. a target id that never
        # appears): keep the caller's frames untouched, matching the
        # historical single-pass behavior.
        return conn_layers, stats

    if dropped_total and vprint is not None:
        passes_txt = (f' in {stats["passes"]} passes'
                      if stats['passes'] > 1 else '')
        if stats['strongest_retained'] is not None:
            # The bound is computed on the table's raw weight column
            # (synapses) — under the connection_ratio basis it does not
            # describe the run's units, so callers suppress it there
            # (round-10) and the exact ratio-unit W* is reported after
            # enumeration instead.
            _bound_txt = (
                f' — strongest '
                f'retained path bottleneck: {stats["strongest_retained"]:g} '
                f'synapses; '
                if report_bottleneck_bound else ' — ')
            _bound_note = (
                f'No admissible path was '
                f'lost; the strongest retained path bottleneck is at most '
                f'{stats["strongest_retained"]:g} synapses (hop-bounded upper '
                f'bound; the exact measured value is reported after '
                f'enumeration) — the top paths and '
                f'their order are unchanged.'
                if report_bottleneck_bound else
                'No admissible path was lost — the top paths and their '
                'order are unchanged (the retained-strength bound is '
                'synapse-unit and is omitted under the connection_ratio '
                'basis; the exact ratio-unit value is reported after '
                'enumeration).')
            vprint(
                f'  Hop-budget pruning (lossless): removed {dropped_total:,} of '
                f'{stats["rows_before"]:,} {label} edges that cannot lie on any '
                f'source->target path within {bound} edges{passes_txt}'
                f'{_bound_txt}'
                f'the strongest (top) paths are unchanged.',
                level='full',
            )
            if warn_notes is not None:
                warn_notes.append(
                    f'- [hop-budget pruning, lossless] {dropped_total:,} of '
                    f'{stats["rows_before"]:,} {label} discovery edges cannot lie '
                    f'on any source->target path within {bound} edges{passes_txt} '
                    f'and were removed before pathfinding. '
                    f'{_bound_note}'
                )
        else:
            vprint(
                f'  Hop-budget pruning (lossless): removed {dropped_total:,} of '
                f'{stats["rows_before"]:,} {label} edges that cannot lie on any '
                f'source->target path within {bound} edges{passes_txt}.',
                level='full',
            )
            if warn_notes is not None:
                warn_notes.append(
                    f'- [hop-budget pruning, lossless] {dropped_total:,} of '
                    f'{stats["rows_before"]:,} {label} discovery edges cannot lie '
                    f'on any source->target path within {bound} edges{passes_txt} '
                    f'and were removed before pathfinding. No admissible path was '
                    f'lost.'
                )
    return current, stats


# Density-capture endpoint classes (auto threshold-density alignment):
# every cone node is classified against the dataset's curated neuron table
# with the shared untyped predicate. 'debris' ids are absent from the table
# (segmentation fragments — never counted), 'untyped' are in-table ids
# whose type label is empty/Unknown/digit-fallback, 'typed' are the rest.
DENSITY_CLS_TYPED, DENSITY_CLS_UNTYPED, DENSITY_CLS_DEBRIS = 0, 1, 2


def _density_table_sets(neuron_df_cache):
    """Curated-id / typed-id sets from loaded neuron tables.

    ``neuron_df_cache`` is the instance's mtime-keyed
    ``_local_neuron_df_cache``. Returns ``(table_ids, typed_ids, known)``;
    ``known=False`` when no table has been loaded, in which case callers
    must not classify (they cannot distinguish debris from typed).
    """
    table_ids, typed_ids = set(), set()
    known = False
    for entry in (neuron_df_cache or {}).values():
        df = entry[1] if isinstance(entry, tuple) else entry
        try:
            if df is None or 'bodyId' not in getattr(df, 'columns', ()):
                continue
            ids = df['bodyId'].astype(str)
            table_ids.update(ids.tolist())
            if 'type' in df.columns:
                untyp = df['type'].map(is_untyped_type_label)
                typed_ids.update(ids[~untyp.astype(bool)].tolist())
            else:
                typed_ids.update(ids.tolist())
            known = True
        except Exception:
            continue
    return table_ids, typed_ids, known


def classify_cone_edges(pre_ids, post_ids, table_ids, typed_ids):
    """Per-edge endpoint class for the density capture (vectorized-ish).

    Returns an int8 array aligned with ``pre_ids``/``post_ids``:
    ``DENSITY_CLS_TYPED`` when both endpoints are typed, else
    ``DENSITY_CLS_UNTYPED`` when both are in the curated table, else
    ``DENSITY_CLS_DEBRIS`` (some endpoint absent from the table).
    """
    import numpy as np

    cls = np.empty(len(pre_ids), dtype=np.int8)
    table_ids = table_ids if table_ids is not None else set()
    typed_ids = typed_ids if typed_ids is not None else set()
    for i, (u, v) in enumerate(zip(pre_ids, post_ids)):
        if u in typed_ids and v in typed_ids:
            cls[i] = DENSITY_CLS_TYPED
        elif u in table_ids and v in table_ids:
            cls[i] = DENSITY_CLS_UNTYPED
        else:
            cls[i] = DENSITY_CLS_DEBRIS
    return cls


def _hop_budget_pass_once(conn_layers, sources, targets, bound,
                          pre_col='bodyId_pre', post_col='bodyId_post',
                          label='bodyId'):
    """One lossless hop-budget pass (see ``prune_layers_hop_budget``).

    Drops every edge (u, v) that cannot lie on ANY simple source->target
    path within ``bound`` edges, BEFORE the pathfinding graph is built:

    1. BFS hop distances distS(.) from the sources and distT(.) to the
       targets over the union of the layer tables.
    2. Keep row (u, v) iff distS(u) + 1 + distT(v) <= bound.

    Exactness: if an admissible simple path through (u, v) exists, its
    prefix/suffix prove distS(u) <= a and distT(v) <= b with
    a + 1 + b <= bound, so the filter NEVER removes an edge that is on a
    path. (The converse only holds for walks, so the filter may keep a
    few edges that no SIMPLE path uses — pruning is lossless, not
    complete.)

    Returns (pruned_tables, stats). Inputs are never mutated —
    the cached FindAllPath graph entries stay shareable across thresholds.
    ``stats`` reports rows_before/rows_dropped/nodes/strongest_retained
    and ``anchored`` (False when no source/target id appears in the
    tables — the caller keeps its frames untouched in that case).
    """
    from collections import deque

    import numpy as np

    tables = [
        c for c in (conn_layers or [])
        if not (c.is_empty() if hasattr(c, 'is_empty') else c.empty)
    ]
    stats = {'rows_before': 0, 'rows_dropped': 0, 'nodes': 0,
             'strongest_retained': None, 'anchored': False}
    if not tables or bound is None or bound < 1:
        return tables, stats

    # Pass 1: intern node strings -> int32 codes and build the union
    # adjacency in one sweep (same memory-conscious scheme as
    # _trim_edges_with_path_integrity). Per-table code arrays are kept for
    # the vectorized mask pass; the row lists themselves are released after
    # each table so the peak stays at one table, not the concat.
    node_codes = {}

    def _code(value):
        existing = node_codes.get(value)
        if existing is None:
            existing = len(node_codes)
            node_codes[value] = existing
        return existing

    adj = {}
    radj = {}
    adj_w = {}  # u -> {v: max weight} for the strongest-retained report
    code_pairs = []  # (pre_codes, post_codes) per table
    for table in tables:
        pre_iter = (table[pre_col].to_list()
                    if hasattr(table, 'iter_rows') else table[pre_col].tolist())
        post_iter = (table[post_col].to_list()
                     if hasattr(table, 'iter_rows') else table[post_col].tolist())
        w_iter = (table['weight'].to_list()
                  if hasattr(table, 'iter_rows') else table['weight'].tolist())
        n = len(pre_iter)
        stats['rows_before'] += n
        pre_codes = np.empty(n, dtype=np.int32)
        post_codes = np.empty(n, dtype=np.int32)
        for i in range(n):
            u = _code(str(pre_iter[i]))
            v = _code(str(post_iter[i]))
            pre_codes[i] = u
            post_codes[i] = v
            w = float(w_iter[i]) if i < len(w_iter) else 1.0
            adj.setdefault(u, set()).add(v)
            radj.setdefault(v, set()).add(u)
            prev_w = adj_w.setdefault(u, {}).get(v)
            if prev_w is None or w > prev_w:
                adj_w[u][v] = w
        code_pairs.append((pre_codes, post_codes))
        del pre_iter, post_iter, w_iter

    stats['nodes'] = len(node_codes)

    def bfs(starts, edges):
        dist = {}
        dq = deque()
        for s in starts:
            if s not in dist:
                dist[s] = 0
                dq.append(s)
        while dq:
            u = dq.popleft()
            du = dist[u] + 1
            for v in edges.get(u, ()):
                if v not in dist:
                    dist[v] = du
                    dq.append(v)
        return dist

    src_codes = [node_codes[str(s)] for s in set(str(x) for x in sources)
                 if str(s) in node_codes]
    tgt_codes = [node_codes[str(s)] for s in set(str(x) for x in targets)
                 if str(s) in node_codes]
    if not src_codes or not tgt_codes:
        # Nothing to anchor the BFS on: keep the tables untouched rather
        # than pruning the whole graph by accident.
        return tables, stats
    stats['anchored'] = True
    dist_s = bfs(src_codes, adj)
    dist_t = bfs(tgt_codes, radj)

    # Pass 2: vectorized mask per table; drop nothing when nothing fails.
    BIG = np.iinfo(np.int64).max // 4
    pruned_tables = []
    dropped_total = 0
    for table, (pre_codes, post_codes) in zip(tables, code_pairs):
        ds = np.fromiter((dist_s.get(int(c), BIG) for c in pre_codes),
                         dtype=np.int64, count=len(pre_codes))
        dt = np.fromiter((dist_t.get(int(c), BIG) for c in post_codes),
                         dtype=np.int64, count=len(post_codes))
        mask = (ds < BIG) & (dt < BIG) & (ds + 1 + dt <= bound)
        dropped = int((~mask).sum())
        dropped_total += dropped
        if dropped == 0:
            pruned_tables.append(table)
            continue
        if hasattr(table, 'iter_rows'):  # polars
            pruned_tables.append(
                table.filter(pl.Series(mask.tolist())))
        else:
            pruned_tables.append(table.loc[mask])
    stats['rows_dropped'] = dropped_total

    # Strongest-retained report (§6b): the widest-path bottleneck of the
    # best source->target path. Pruning is lossless, so this value is
    # IDENTICAL before and after pruning — stating it tells the user the
    # top paths are untouched by the pass. Computed unconditionally so the
    # stats contract is stable.
    strongest_retained = None
    import heapq
    INF = float('inf')
    best = {c: INF for c in src_codes}
    heap = [(-INF, c) for c in src_codes]
    heapq.heapify(heap)
    settled = set()
    while heap:
        neg_b, u = heapq.heappop(heap)
        b = -neg_b
        if u in settled:
            continue
        settled.add(u)
        for v, w in adj_w.get(u, {}).items():
            nb = min(b, w)
            if nb > best.get(v, -INF):
                best[v] = nb
                heapq.heappush(heap, (-nb, v))
    cand = [best[c] for c in tgt_codes if c in best]
    if cand:
        strongest_retained = max(cand)
    stats['strongest_retained'] = strongest_retained

    stats['rows_dropped'] = dropped_total
    return pruned_tables, stats


def apply_edge_budget_floor(conn_layers, budget, sources, targets, bound,
                            pre_col='bodyId_pre', post_col='bodyId_post',
                            vprint=None, warn_notes=None):
    """Lossy Edge-Budget floor (Fix D): w0 = (N-th strongest edge) + 1.

    After the lossless prunes, when the pruned cone still exceeds
    ``budget`` edges, the N-th strongest edge's weight w1 is located
    (O(E) quickselect) and every edge with ``weight < w1 + 1`` is
    dropped. Edges STRICTLY heavier than w1 number fewer than N by
    definition of the N-th rank, so the floored cone always fits the
    budget — the boundary-tie mass (millions of equal-weight weak
    edges) cannot blow it up, and on locally truncated products (e.g.
    BANC at weight >= 3) a landing at w1 = 3 floors at 4 instead of
    being a no-op.

    Semantics: the floor is a pure threshold raise — the run is exactly
    a complete run at ``max(asked threshold, w0)``; every enumerated
    path has bottleneck >= w0, so the reported tau satisfies
    tau >= w0. Reported honestly as a LOSSY stage: paths with
    bottleneck < w0 do not exist in the output.

    A cheap second lossless pass (``prune_layers_hop_budget``) re-runs
    on the floored tables to drop edges whose routes died with the
    floor. Inputs are never mutated — cached graph entries stay
    shareable.

    Returns (floored_tables, stats) with stats: {applied,
    edges_before, landing (w1), floor (w0), edges_after, dropped,
    prune_dropped, strongest_retained}.
    """
    import numpy as np

    tables = [
        c for c in (conn_layers or [])
        if not (c.is_empty() if hasattr(c, 'is_empty') else c.empty)
    ]
    stats = {'applied': False, 'edges_before': 0, 'landing': None,
             'floor': None, 'edges_after': 0, 'dropped': 0,
             'prune_dropped': 0, 'strongest_retained': None}
    if not tables or not budget or int(budget) < 1:
        return conn_layers, stats
    budget = int(budget)

    weight_arrays = []
    total = 0
    for table in tables:
        w = (table['weight'].to_list() if hasattr(table, 'iter_rows')
             else table['weight'].tolist())
        weight_arrays.append(np.asarray(w, dtype=np.float64))
        total += len(w)
    stats['edges_before'] = total
    if total <= budget:
        return conn_layers, stats

    weights = np.concatenate(weight_arrays)
    # N-th strongest edge weight (ascending partition indexed from the
    # top); O(E).
    kth = total - budget
    w1 = float(np.partition(weights, kth)[kth])
    w0 = w1 + 1.0

    floored_tables = []
    after = 0
    for table, w in zip(tables, weight_arrays):
        mask = w >= w0
        kept = int(mask.sum())
        after += kept
        if kept == len(w):
            floored_tables.append(table)
            continue
        if hasattr(table, 'iter_rows'):  # polars
            floored_tables.append(table.filter(pl.Series(mask.tolist())))
        else:
            floored_tables.append(table.loc[mask])
    stats['landing'] = w1
    stats['floor'] = w0
    stats['edges_after'] = after
    stats['dropped'] = total - after

    # Production semantics (user directive): the Edge Budget is honored
    # RESTRICTIVELY — no degenerate revert. When flooring empties the
    # cone (the top-N edges share one weight tier, or the second
    # lossless pass strands every route), the empty result IS the
    # correct answer: the run is exactly a complete run at w0 finding
    # no paths. The notices below say so; raise the Edge Budget to keep
    # weaker tiers.

    # Second lossless pass on the floored tables (routes that died with
    # the floor can strand further dead edges; still O(E), still
    # lossless).
    floored_tables, prune_stats = prune_layers_hop_budget(
        floored_tables, sources, targets, bound,
        pre_col=pre_col, post_col=post_col,
        vprint=None, warn_notes=None,
        max_passes=1,
    )
    stats['prune_dropped'] = prune_stats.get('rows_dropped', 0)
    stats['strongest_retained'] = prune_stats.get('strongest_retained')
    surviving = sum(
        f.height if hasattr(f, 'height') else len(f)
        for f in floored_tables)
    degenerate_empty = after == 0 or surviving == 0
    stats['applied'] = True

    if vprint is not None:
        vprint(
            f'  Edge budget (lossy floor): pruned cone exceeded {budget:,} '
            f'edges ({total:,}). Top-N landing w1 = {w1:g}, applied floor '
            f'w0 = w1 + 1 = {w0:g} — {stats["dropped"]:,} edges dropped '
            f'({total:,} -> {after:,}'
            + (f', second lossless pass -{stats["prune_dropped"]:,}'
               if stats['prune_dropped'] else '')
            + f'). Equivalent to a complete run at min synapse = {w0:g}; '
            f'paths with bottleneck < {w0:g} do not exist in this output.',
            level='always')
    if warn_notes is not None:
        strongest_txt = (
            f' Strongest retained path bottleneck: '
            f'{stats["strongest_retained"]:g} synapses.'
            if stats['strongest_retained'] is not None else '')
        degenerate_txt = (
            ' NOTE: the floored cone is EMPTY — the run found no paths.'
            if degenerate_empty else '')
        warn_notes.append(
            '- [edge budget, lossy floor] the lossless-pruned cone '
            f'exceeded the edge budget ({stats["edges_before"]:,} edges > '
            f'{budget:,}). Floor applied: top-N landing w1 = {w1:g}, '
            f'w0 = w1 + 1 = {w0:g} — {stats["dropped"]:,} edges dropped '
            f'({stats["edges_before"]:,} -> {stats["edges_after"]:,}'
            + (f', second lossless pass -{stats["prune_dropped"]:,}'
               if stats['prune_dropped'] else '')
            + f').{strongest_txt}{degenerate_txt} This run is exactly a '
            f'complete run at min synapse = {w0:g}: paths with '
            f'bottleneck < {w0:g} do not exist in the output. Raise the '
            'Edge Budget to keep weaker tiers.')
    return floored_tables, stats


def fit_edge_budget(conn_layers, budget, sources, targets, bound,
                    pre_col='bodyId_pre', post_col='bodyId_post',
                    vprint=None, warn_notes=None, max_probes=8):
    """Budget-fit search (§7.4): the weakest weight tier whose lossless-
    closed cone fits ``budget``.  Synapse-basis contract (integer tiers,
    landing w1+1); the connection-ratio basis uses
    ``connection_ratio_paths.fit_edge_budget_ratio`` (float tiers, weakest
    distinct tier above w1).

    Refines the one-shot Fix D landing (``apply_edge_budget_floor``): that
    landing floors at ``w0 = w1 + 1`` — excluding the boundary-tie mass —
    and discards whatever slack the closure leaves unused, which on real
    connectomes can be most of the cap. The fit search instead probes weight
    tiers downward from the one-shot landing (gallop, then bisect between
    the last fitting and first overshooting tier) and floors at the weakest
    tier whose single-pass-closed cone still has <= ``budget`` rows. Every
    probe is a pure threshold raise, so the floored run is exactly a
    complete run at ``min_synapse_num = t*``; the cap is honored whenever
    any tier fits, and zero-count probes count as fits (a weaker tier can
    revive the cone).

    Returns (tables, stats). ``tables`` are the floored layer tables of the
    winning tier (the caller's frames unchanged unless a floor was applied).
    ``stats`` carries ``applied``/``floor`` (= t*)/``landing`` (the first
    overshooting tier weight — the budget boundary)/``edges_before``/
    ``edges_after`` (kept rows)/``dropped``/``strongest_retained`` plus the
    fit-specific ``floor_skipped`` (the full closed cone already fits the
    cap), ``budget_fully_used``, ``probes``, ``truncated``,
    ``residual_slack``, ``search_seconds`` and ``probe_trace``
    [(weight, closed rows, seconds)].
    """
    import time as _time
    import numpy as np

    stats = {'applied': False, 'edges_before': 0, 'landing': None,
             'floor': None, 'edges_after': 0, 'dropped': 0,
             'strongest_retained': None, 'floor_skipped': False,
             'budget_fully_used': False, 'probes': 0, 'truncated': False,
             'residual_slack': None, 'search_seconds': 0.0, 'probe_trace': []}
    t_search = _time.perf_counter()

    tables = [c for c in (conn_layers or [])
              if not (c.is_empty() if hasattr(c, 'is_empty') else c.empty)]
    if not tables or not budget or int(budget) < 1:
        return conn_layers, stats
    budget = int(budget)

    weight_arrays = []
    total = 0
    for table in tables:
        w = (table['weight'].to_list() if hasattr(table, 'iter_rows')
             else table['weight'].tolist())
        weight_arrays.append(np.asarray(w, dtype=np.float64))
        total += len(w)
    stats['edges_before'] = total
    if total <= budget:
        stats['floor_skipped'] = True
        stats['status'] = 'no_floor_needed'
        stats['search_seconds'] = _time.perf_counter() - t_search
        if vprint is not None:
            vprint(
                f'  Edge budget (budget-fit): the lossless-pruned cone '
                f'({total:,} rows) already fits the cap {budget:,} — '
                f'no floor applied.',
                level='always')
        return conn_layers, stats

    all_weights = np.concatenate(weight_arrays)

    def probe(weight):
        p0 = _time.perf_counter()
        masked = [t.filter(pl.col('weight') >= weight)
                  if hasattr(t, 'iter_rows')
                  else t[t['weight'] >= weight] for t in tables]
        closed, _pstats = prune_layers_hop_budget(
            masked, sources, targets, bound,
            pre_col=pre_col, post_col=post_col, max_passes=1)
        closed_rows = sum(c.height if hasattr(c, 'height') else len(c)
                          for c in closed)
        stats['probes'] += 1
        stats['probe_trace'].append(
            (weight, closed_rows, _time.perf_counter() - p0))
        return closed, closed_rows, _pstats.get('strongest_retained')

    # One-shot landing (quickselect), canonicalized to the weakest tier
    # at or above t_raw — that tier reproduces the same cone
    # (E(t_raw) == E(landing_w)), so probes are tier weights.
    kth = total - budget
    w1 = float(np.partition(all_weights, kth)[kth])
    t_raw = w1 + 1.0
    distinct = sorted({float(x) for x in all_weights.tolist()}, reverse=True)
    landing_w = next((w for w in sorted(distinct) if w >= t_raw), None)

    best_t, best_closed, best_rows = None, None, 0
    lo_idx = None
    if landing_w is not None:
        best_t = landing_w
        best_closed, best_rows, best_strongest = probe(landing_w)
        stats['strongest_retained'] = best_strongest
        lo_idx = distinct.index(landing_w)
        start = lo_idx + 1
    else:
        start = 0
    hi_idx = None
    i, step = start, 1
    while i < len(distinct) and stats['probes'] < max_probes:
        closed, rows, strongest = probe(distinct[i])
        if rows <= budget:            # empty counts fit: revival possible
            best_t, best_closed, best_rows = distinct[i], closed, rows
            stats['strongest_retained'] = strongest
            lo_idx = i
            i += step
            step *= 2
        else:
            hi_idx = i
            break
    if hi_idx is None and i >= len(distinct) and lo_idx is not None \
            and lo_idx < len(distinct) - 1:
        hi_idx = len(distinct)        # virtual boundary: the tail is unseen
    while hi_idx is not None and lo_idx is not None and hi_idx - lo_idx > 1 \
            and stats['probes'] < max_probes:
        mid = (lo_idx + hi_idx) // 2
        closed, rows, strongest = probe(distinct[mid])
        if rows <= budget:
            best_t, best_closed, best_rows = distinct[mid], closed, rows
            stats['strongest_retained'] = strongest
            lo_idx = mid
        else:
            hi_idx = mid
    stats['truncated'] = (
        (hi_idx is not None and lo_idx is not None and hi_idx - lo_idx > 1)
        or (hi_idx is None and lo_idx is not None
            and lo_idx < len(distinct) - 1))
    stats['budget_fully_used'] = hi_idx is not None
    stats['search_seconds'] = _time.perf_counter() - t_search

    if lo_idx is not None and lo_idx == len(distinct) - 1 and best_rows > 0:
        # The bottom tier fits: the whole lossless-closed cone fits the cap.
        stats['floor_skipped'] = True
        stats['status'] = 'no_floor_needed'
        if vprint is not None:
            vprint(
                f'  Edge budget (budget-fit): even the full lossless-closed '
                f'cone ({total:,} rows) fits the cap {budget:,} — no floor '
                f'applied ({stats["probes"]} probes, '
                f'{stats["search_seconds"]:.1f}s).',
                level='always')
        if warn_notes is not None:
            warn_notes.append(
                '- [edge budget, budget-fit] no floor applied: the full '
                'lossless-closed cone '
                f'({stats["edges_before"]:,} edges) fits the cap '
                f'({budget:,}).')
        return best_closed, stats

    if not best_closed or best_rows == 0:
        stats['status'] = 'declined'
        stats['search_seconds'] = _time.perf_counter() - t_search
        if vprint is not None:
            vprint(
                f'  Edge budget (budget-fit): no non-empty floor fits the '
                f'cap {budget:,} — floor not applied; the full cone was '
                f'kept.',
                level='always')
        if warn_notes is not None:
            warn_notes.append(
                '- [edge budget, budget-fit] NOT applied: no weight tier '
                f'yields a non-empty closed cone within the cap '
                f'({budget:,}). The full cone was kept '
                f'({stats["edges_before"]:,} edges).')
        return conn_layers, stats

    if hi_idx is not None:
        # hi_idx may be the virtual end-of-list boundary (the tail beyond the
        # bracket was never probed); the honest landing tier is then the
        # weakest real tier, not distinct[len(distinct)].
        stats['landing'] = distinct[min(hi_idx, len(distinct) - 1)]
    stats['floor'] = best_t
    stats['edges_after'] = best_rows
    stats['dropped'] = total - best_rows
    stats['residual_slack'] = budget - best_rows
    stats['applied'] = True
    stats['status'] = 'floored'

    if vprint is not None:
        vprint(
            f'  Edge budget (budget-fit): pruned cone exceeded {budget:,} '
            f'edges ({total:,}). Floored at t* = {best_t:g} after '
            f'{stats["probes"]} probes ({stats["search_seconds"]:.1f}s) — '
            f'{stats["dropped"]:,} edges dropped ({total:,} -> '
            f'{best_rows:,}; residual slack {stats["residual_slack"]:,}'
            + (f'; next tier {stats["landing"]:g} would exceed the cap'
               if stats['landing'] is not None else '')
            + (', SEARCH TRUNCATED at the probe budget'
               if stats['truncated'] else '')
            + f'). Equivalent to a complete run at min synapse = {best_t:g}; '
            f'paths with bottleneck < {best_t:g} do not exist in this '
            f'output.',
            level='always')
    if warn_notes is not None:
        strongest_txt = (
            f' Strongest retained path bottleneck: '
            f'{stats["strongest_retained"]:g} synapses.'
            if stats['strongest_retained'] is not None else '')
        warn_notes.append(
            '- [edge budget, budget-fit] the lossless-pruned cone exceeded '
            f'the edge budget ({stats["edges_before"]:,} edges > '
            f'{budget:,}). Floor applied: t* = {best_t:g} after '
            f'{stats["probes"]} probes — {stats["dropped"]:,} edges dropped '
            f'({stats["edges_before"]:,} -> {stats["edges_after"]:,}; '
            f'residual slack {stats["residual_slack"]:,}).'
            + (f' The next weaker tier ({stats["landing"]:g}) would exceed '
               'the cap — the budget is fully used.'
               if stats['budget_fully_used'] else '')
            + (' NOTE: the search was truncated at the probe budget; a '
               'weaker tier might still fit.'
               if stats['truncated'] else '')
            + f'{strongest_txt} This run is exactly a complete run at '
            f'min synapse = {best_t:g}: paths with bottleneck < {best_t:g} '
            'do not exist in the output.')
    return best_closed, stats


def _format_provenance_value(value):
    """Human-readable parameters.txt rendering for a provenance value.

    Floats render with ``repr`` (shortest roundtrip-exact form): ratio
    tiers are arbitrary float64 divisions, and a ``%g`` stamp loses
    digits the post-hoc consumers parse back (the refill's cut
    re-derivation would exclude boundary edges at the floor tier)."""
    if value is None:
        return 'n/a'
    if isinstance(value, bool):
        return str(value)
    if isinstance(value, float):
        return repr(value)
    return str(value)


def clear_findallpath_cache(dataset: str = None):
    """
    Clear the module-level FindAllPath graph cache.
    
    Args:
        dataset: Specific dataset to clear. If None, clears all.
    """
    global _FINDALLPATH_GRAPH_CACHE
    if dataset is None:
        _FINDALLPATH_GRAPH_CACHE.clear()
    else:
        # Cache keys are built from the NORMALIZED dataset name
        # (dataset_safe: ':' and '.' replaced with '_'), so matching must
        # normalize too - otherwise e.g. 'hemibrain:v1.2.1' never matches
        # 'hemibrain_v1_2_1_...' and the clear silently no-ops.
        dataset_safe = canonical_dataset_name(dataset).replace(':', '_').replace('.', '_')
        keys_to_delete = [
            k for k in _FINDALLPATH_GRAPH_CACHE
            if k.startswith(dataset_safe) or k.startswith(dataset)
        ]
        for k in keys_to_delete:
            del _FINDALLPATH_GRAPH_CACHE[k]


def clear_fnc_cache(dataset: str = None):
    """
    Clear the module-level FindNeuronConnection cache.
    
    Args:
        dataset: Specific dataset to clear (e.g., 'hemibrain_v1_2_1'). If None, clears all.
    """
    global _FNC_CACHE
    if dataset is None:
        _FNC_CACHE.clear()
    elif dataset in _FNC_CACHE:
        del _FNC_CACHE[dataset]


